refused_program.body:
set -euo pipefail
while IFS=$'\t' read -r old new; do
  if awk -v key="$old" -F= '
    {
      k=$1; sub(/^[[:space:]]+/,"",k); sub(/[[:space:]]+$/,"",k);
      if (k == key) found=1
    }
    END { exit !found }' config/local.conf; then
    old_re=$(printf '%s' "$old" | sed 's/[^A-Za-z0-9_]/\\&/g')
    new_repl=$(printf '%s' "$new" | sed 's/[&\\]/\\&/g')
    sed -i -E "s/^([[:space:]]*)${old_re}([[:space:]]*=)/\1${new_repl}\2/" config/local.conf
  fi
done < <(cat config/renames.conf | awk -F= '
  /^[[:space:]]*#/ { next }
  NF >= 2 {
    o=$1; n=$2;
    sub(/^[[:space:]]+/,"",o); sub(/[[:space:]]+$/,"",o);
    sub(/[[:space:]]*#.*$/,"",n);
    sub(/^[[:space:]]+/,"",n); sub(/[[:space:]]+$/,"",n);
    if (o != "" && n != "") print o "\t" n
  }')

postconditions.probe:
old_keys=$(cat config/renames.conf | awk -F= '
