  NF >= 2 {
    o=$1; n=$2;
    sub(/^[[:space:]]+/,"",o); sub(/[[:space:]]+$/,"",o);
    sub(/[[:space:]]*#.*$/,"",n);
    sub(/^[[:space:]]+/,"",n); sub(/[[:space:]]+$/,"",n);
    if (o != "" && n != "") print n
  }' | sort -u)
local_keys=$(awk -F= '
  /^[[:space:]]*#/ { next }
  NF >= 1 {
    k=$1; sub(/^[[:space:]]+/,"",k); sub(/[[:space:]]+$/,"",k);
    if (k != "") print k
  }' config/local.conf | sort -u)
if ! grep -qFxf <(printf '%s\n' "$new_keys") <(printf '%s\n' "$local_keys"); then
  exit 1
fi
if grep -qFxf <(printf '%s\n' "$old_keys") <(printf '%s\n' "$local_keys"); then
  exit 1
fi

